<?php
declare(strict_types=1);

namespace wise\agent\security;

use wise\agent\contract\ToolInterface;
use wise\agent\skill\contract\SkillInterface;

/**
 * 能力访问元数据归一化器
 *
 * 把 Tool / Skill 归一化为 `CapabilityDescriptor`，供
 * 「鉴权（CapabilityAuthorizer）」与「权限注册（ToolPermissionRegistrar）」共用，
 * 保证两处口径完全一致（历史问题：两处各自推断，导致鉴权与权限表标识分裂）。
 *
 * 访问类型 / 风险等级的**默认值由能力自身给出**：
 *   - Tool：`BaseTool` 默认 execute + medium；`AutoGeneratedTool` / `BaseAutoTool`
 *     按 toolType 推导；各内置工具与能力工具按实际语义声明
 *
 * 本类只负责：读取元数据 → 归一化 → 补齐权限标识与归属插件。
 */
class AccessResolver
{
    /**
     * 解析工具能力描述
     */
    public function resolveTool(ToolInterface $tool, ?string $name = null): CapabilityDescriptor
    {
        $name       = $name ?? $tool->getName();
        $permission = (string) $tool->getPermission();

        return new CapabilityDescriptor(
            CapabilityDescriptor::KIND_TOOL,
            $name,
            $permission,
            CapabilityAccess::normalize($tool->getAccess()),
            $this->normalizeRisk($tool->getRiskLevel()),
            $this->safeDescription($tool),
            $this->inferPlugin($permission)
        );
    }

    /**
     * 解析 Skill 能力描述
     *
     * 权限标识取能力自身声明（约定 `ai.skill.{name}`）；
     * 空值兜底为 `ai.skill.{name}`，保证 Skill 一定受控。
     */
    public function resolveSkill(SkillInterface $skill): CapabilityDescriptor
    {
        $name       = $skill->getName();
        $permission = trim((string) $skill->getPermission());

        if ($permission === '') {
            $permission = CapabilityAccess::SKILL_PREFIX . '.' . $name;
        }

        return new CapabilityDescriptor(
            CapabilityDescriptor::KIND_SKILL,
            $name,
            $permission,
            CapabilityAccess::normalize($skill->getAccess()),
            $this->normalizeRisk($skill->getRiskLevel()),
            (string) $skill->getDescription(),
            $this->inferPlugin($permission, (string) $skill->getSource())
        );
    }

    /**
     * 由权限标识 / 来源推断归属插件
     */
    public function inferPlugin(string $permission, string $source = ''): string
    {
        if (str_starts_with($permission, 'plugin:')) {
            $rest  = substr($permission, 7);
            $ident = explode('.', $rest)[0] ?? '';

            return $ident !== '' ? $ident : $this->pluginFallback();
        }

        if (str_starts_with($source, 'plugin:')) {
            return substr($source, 7);
        }

        return $this->pluginFallback();
    }

    /**
     * 安全获取工具描述（部分工具可能抛异常）
     */
    protected function safeDescription(ToolInterface $tool): string
    {
        try {
            return (string) $tool->getDescription();
        } catch (\Throwable) {
            return '';
        }
    }

    /**
     * 风险等级归一化（非法值回退 medium）
     */
    protected function normalizeRisk(string $risk): string
    {
        $risk = strtolower(trim($risk));

        return in_array($risk, [
            CapabilityAccess::RISK_LOW,
            CapabilityAccess::RISK_MEDIUM,
            CapabilityAccess::RISK_HIGH,
        ], true) ? $risk : CapabilityAccess::RISK_MEDIUM;
    }

    /**
     * 平台自带能力的归属标识
     */
    protected function pluginFallback(): string
    {
        return 'wise-agent';
    }
}
